import {createGame,activePlayers,submitOrder,resolveRound,commitDecisions,winners,money,market,prepareAutoMarket,migrateGame,STAGES,getStage} from './engine.js';

const root=document.querySelector('#app'),KEY='fx-survival-v1';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={active:'続行',fixed:'資産確定',cut:'ロスカット',debt:'負債・退場',empty:'資金枯渇'};
let game=null,setupCount=4,setupMode='auto',setupStage='classic',setupNames=['プレイヤーA','プレイヤーB','プレイヤーC','プレイヤーD','プレイヤーE','プレイヤーF'];
let draftSide=null,draftLeverage=1,storageError=false,drawStep=0;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1&&saved.players?.length>=2&&saved.players.length<=6){saved.players.forEach(p=>{BigInt(p.wealth);BigInt(p.peak);BigInt(p.maxPosition)});game=migrateGame(saved)}}catch{storageError=true}
function save(){try{if(game)localStorage.setItem(KEY,JSON.stringify(game));else localStorage.removeItem(KEY)}catch{storageError=true}}
function update(scroll=true){save();render();if(scroll)window.scrollTo({top:0,behavior:'instant'})}
function current(){return activePlayers(game)[game.cursor]}
function avatar(p){return `<span class="avatar">${String.fromCharCode(65+p.id)}</span>`}
function playerLabel(p){return `<div class="player-label">${avatar(p)}<span>${escape(p.name)}</span></div>`}
function action(label,a,cls='primary full'){return `<button type="button" class="${cls}" data-action="${a}">${label}</button>`}
function activeStage(){return getStage(game?.stage??setupStage)}
function stageSheet(stage){return `<div class="table-wrap"><table class="stage-table"><thead><tr><th>出目</th><th>第1サイコロ</th><th>急変判定</th></tr></thead><tbody>${[1,2,3,4,5,6].map(n=>`<tr><td>${n}</td><td>${n===6?'もう一度':`${stage.normal[n-1]/100}%`}</td><td class="${n>=4?'gap-text':''}">${stage.shock[n-1]/100}%${n>=4?'（ギャップ）':''}</td></tr>`).join('')}</tbody></table></div><p class="stage-explanation">急変判定は、第1サイコロで6が出た場合だけ。第2サイコロの4〜6がギャップです。</p>`}
function stageSelection(){return `<fieldset class="stage-picker"><legend>ステージ（全員共通）</legend><div class="stage-options">${Object.values(STAGES).map(stage=>`<button type="button" data-stage="${stage.id}" class="stage-option ${setupStage===stage.id?'stage-selected':''}" aria-pressed="${setupStage===stage.id}"><span class="stage-heading"><strong>${stage.name}</strong><small>${stage.code}</small></span><span class="stage-description">${stage.description}</span><span class="stage-numbers">通常 ${stage.normal[0]/100}〜${stage.shock[2]/100}% · ギャップ ${stage.shock.slice(3).map(n=>n/100+'%').join(' / ')}</span></button>`).join('')}</div><p class="stage-explanation">全ステージ共通：上昇／下落は50:50。ギャップ発生率は1/12（約8.3%）。開始後は変更できません。</p><details class="stage-details"><summary>${getStage(setupStage).name}の出目と値動き</summary>${stageSheet(getStage(setupStage))}</details><p class="stage-explanation">通貨ステージは、通貨のイメージを使ったゲーム用の設定です。</p></fieldset>`}
function stageBadge(){const stage=activeStage();return `<div class="stage-active" data-stage-active="${stage.id}"><strong>${stage.name}</strong><span>全員共通</span></div>`}
function diceLegend(shock){const values=shock?activeStage().shock:activeStage().normal;const entries=[1,2,3,4,5,6].map(n=>`${n}：${n===6&&!shock?'急変判定':values[n-1]/100+'%'}`);return entries.slice(0,3).join(' / ')+'<br>'+entries.slice(3).join(' / ')}
function showRules(){const stage=activeStage();document.querySelector('#rules-market').innerHTML=`<h3>値動き · ${stage.name}</h3><p>開始時に選んだステージで、全員が同じ相場を経験します。ゲーム途中で変更できません。</p>${stageSheet(stage)}<p>ギャップ発生率は全ステージ1/12（約8.3%）。通常相場では0円でロスカット、ギャップ相場では負債が発生することがあります。</p>`;document.querySelector('#rules').showModal()}
function publicBoard(){return `<aside class="public-panel"><h2>みんなの資産</h2><p class="muted">公開情報 · 取引中 ${activePlayers(game).length}人</p>${game.players.map(p=>`<div class="player-row"><div class="player-heading">${avatar(p)}<strong>${escape(p.name)}</strong><span class="status ${p.status}">${labels[p.status]}</span></div><div class="wealth ${BigInt(p.wealth)<0n?'negative':''}">${money(p.wealth)}</div><div class="mini-stats"><span>最高到達 ${money(p.peak)}</span><span>最大取引額 ${money(p.maxPosition)}</span></div></div>`).join('')}<div class="reset-row">${action('ゲームを終了','reset','text-button')}</div></aside>`}
function setup(){return `<div class="setup-layout"><section class="surface"><p class="eyebrow">NEW GAME</p><h1>テーブルに集まろう。</h1><p class="muted setup-note">名前を決めて、1台のスマホで始めましょう。</p><form id="setup-form"><label>プレイヤー人数 <span class="muted">（3〜6人推奨）</span></label><div class="counts">${[2,3,4,5,6].map(n=>`<button type="button" data-count="${n}" class="secondary ${setupCount===n?'selected':''}" aria-pressed="${setupCount===n}">${n}人</button>`).join('')}</div><div class="names">${setupNames.slice(0,setupCount).map((n,i)=>`<label>プレイヤー${String.fromCharCode(65+i)}<input name="name-${i}" data-name="${i}" value="${escape(n)}" maxlength="20" required autocomplete="off"></label>`).join('')}</div>${stageSelection()}<label>相場の決め方</label><div class="mode-choice"><button type="button" data-mode="auto" class="secondary ${setupMode==='auto'?'selected':''}" aria-pressed="${setupMode==='auto'}">アプリで振る</button><button type="button" data-mode="manual" class="secondary ${setupMode==='manual'?'selected':''}" aria-pressed="${setupMode==='manual'}">実物の出目を入力</button></div><p class="muted setup-note" style="margin:12px 0 0">${setupMode==='auto'?'鉛筆の＋／−も、サイコロもアプリで抽選。':'鉛筆の＋／−と、サイコロの1〜6を入力。'}</p><button class="primary full" type="submit">このメンバーで始める</button><p class="error" id="form-error" role="alert"></p></form></section><aside class="surface setup-aside"><p class="eyebrow">THE RULES</p><h2>増やす。降りる。<br>最後に残した人が勝つ。</h2><div class="rule-stats"><div><strong>100<span>万円</span></strong><span>初期資産</span></div><div><strong>12<span>ラウンド</span></strong><span>ゲームの長さ</span></div><div><strong>1–100<span>倍</span></strong><span>選べるレバレッジ</span></div><div><strong>2–6<span>人</span></strong><span>対面でプレイ</span></div></div><ol class="steps"><li>売買と倍率を秘密に決め、全員で公開。</li><li>同じ相場で、全員の損益を精算。</li><li>続けるか、資産を確定して降りるか。</li></ol><p class="tip">資産はいつでも公開。<br>注文は全員の確定まで秘密。<br>進退は全員で同時に宣言。</p></aside></div>`}
function decisionSummary(){const previous=game.lastDecisions;if(!previous)return '';return `<div class="decision-summary" role="status"><p>第${previous.round}ラウンドの進退</p><div>${previous.choices.map(({id,choice})=>`<span><strong>${escape(game.players.find(p=>p.id===id).name)}</strong> ${choice==='fix'?'資産確定':'続行'}</span>`).join('')}</div></div>`}
function order(){const p=current(),valid=Number.isInteger(draftLeverage)&&draftLeverage>=1&&draftLeverage<=100;return `${decisionSummary()}${playerLabel(p)}${inputProgress()}<h1>今回、どう取引する？</h1><p class="muted">現在資産 ${money(p.wealth)} · 全員の確定後に自動公開</p><form id="order-form"><label>売買方向</label><div class="choice-grid">${[['buy','買い','上昇で利益'],['sell','売り','下落で利益']].map(([side,name,desc])=>`<button type="button" data-side="${side}" class="${draftSide===side?'selected':''}" aria-pressed="${draftSide===side}"><strong class="${side}">${name}</strong><small>${desc}</small></button>`).join('')}</div><label for="leverage">レバレッジ</label><div class="input-row"><button type="button" class="secondary" data-adjust="-1" aria-label="レバレッジを1下げる">−</button><input id="leverage" name="leverage" type="number" min="1" max="100" step="1" value="${draftLeverage}" inputmode="numeric" required><span>倍</span><button type="button" class="secondary" data-adjust="1" aria-label="レバレッジを1上げる">＋</button></div><input type="range" id="leverage-range" aria-label="レバレッジ" min="1" max="100" step="1" value="${draftLeverage}"><div class="range-labels"><span>1倍</span><span>100倍</span></div><div class="position"><span>今回の取引額 · 現在資産 × 倍率</span><strong id="position-value">${valid?money(BigInt(p.wealth)*BigInt(draftLeverage)):'1〜100の整数を入力'}</strong></div><button type="submit" class="primary full" id="order-submit" ${draftSide&&valid?'':'disabled'}>${game.cursor+1===activePlayers(game).length?'注文を確定して全員分を公開':'注文を確定して次の人へ'}</button><p class="error" id="form-error" role="alert"></p></form>`}
function inputProgress(){return `<p class="input-progress">${game.cursor+1} / ${activePlayers(game).length}人目 · 他の人に見せずに入力</p>`}
function orderList(){return activePlayers(game).map(p=>{const o=game.orders[p.id];return `<div class="order-card"><div class="order-line"><strong>${escape(p.name)}</strong><span class="${o.side==='buy'?'positive':'negative'}">${o.side==='buy'?'買い':'売り'} <b>${o.leverage}倍</b></span></div><p>取引額 <strong>${money(BigInt(p.wealth)*BigInt(o.leverage))}</strong></p></div>`}).join('')}
function marketFacts(){return `<div class="market-facts">${game.direction?`<span class="chip ${game.direction==='up'?'positive':'negative'}">${game.direction==='up'?'＋ 上昇':'− 下落'}</span>`:''}${game.first?`<span class="chip">第1サイコロ ${game.first}</span>`:''}${game.second?`<span class="chip">第2サイコロ ${game.second}</span>`:''}</div>`}
function marketView(){
 const phase=game.phase;
 if(phase==='orders-revealed')return `<p class="eyebrow">POSITIONS OPEN</p><h1>今回のポジション</h1><p class="muted">全員の注文・倍率・取引額を公開。</p>${orderList()}${game.mode==='auto'?action('アプリで相場を抽選','draw-market'):`<p class="muted" style="margin-top:20px">実物の鉛筆を転がして、結果を選んでください。</p><div class="choice-grid"><button data-direction="up"><strong class="buy">＋ 上昇</strong></button><button data-direction="down"><strong class="sell">− 下落</strong></button></div>`}`;
 if(phase==='drawing')return `<p class="eyebrow">MARKET DRAW</p><h1>相場を抽選中…</h1><div class="market-banner" aria-live="polite">${drawStep===0?'<div class="big draw-pulse">＋ / −</div><p>相場方向と値動きをアプリで抽選</p>':`<div class="big ${game.direction==='up'?'positive':'negative'}">${game.direction==='up'?'＋ 上昇':'− 下落'}</div><p>第1サイコロ：${game.first}</p>${game.first===6?`<p class="gap-text">6が出た。急変判定へ。</p>${drawStep>=2?`<p>第2サイコロ：${game.second}</p>`:''}`:''}`}</div>`;
 const shock=phase==='shock';return `<p class="eyebrow">${shock?'VOLATILITY CHECK':'PRICE MOVEMENT'}</p><h1>${shock?'6が出た。急変判定。':'値動きを決めよう。'}</h1>${marketFacts()}<p class="muted">${shock?'4・5・6ならギャップ相場。':'6が出たら急変判定へ。'}</p>${game.mode==='auto'?action('アプリで残りの抽選を実行','draw-market'):`<p>実物の${shock?'第2':'第1'}サイコロの出目を入力。</p><div class="dice-grid">${[1,2,3,4,5,6].map(n=>`<button data-face="${n}">${n}</button>`).join('')}</div>`}<p class="tip">${diceLegend(shock)}</p>`;
}
function batchChoices(p){const choice=game.decisions[p.id];return `<div class="batch-choices" role="group" aria-label="${escape(p.name)}の進退">${[['continue','続行'],['fix','資産確定']].map(([value,label])=>`<button type="button" class="secondary ${choice===value?'selected':''}" data-player="${p.id}" data-decision="${value}" aria-pressed="${choice===value}">${label}</button>`).join('')}</div>`}
function resultCards(h,withChoices=false){return h.results.map(r=>{const p=game.players.find(p=>p.id===r.id);return `<div class="result-card"><div class="order-line"><strong>${escape(p.name)}</strong><span class="status ${p.status}">${withChoices&&p.status==='active'?'取引中':labels[p.status]}</span></div><small>${r.side==='buy'?'買い':'売り'} ${r.leverage}倍 · 取引額 ${money(r.position)}</small><div class="results-money"><strong class="${BigInt(r.after)<0n?'negative':''}">${money(r.after)}</strong><span class="${BigInt(r.pnl)>=0n?'positive':'negative'}">${BigInt(r.pnl)>0n?'＋':''}${money(r.pnl)}</span></div><small>${money(r.before)} → ${money(r.after)}</small>${withChoices&&p.status==='active'?batchChoices(p):''}</div>`}).join('')}
function resultView(){const h=game.history.at(-1),active=activePlayers(game),recorded=active.filter(p=>['continue','fix'].includes(game.decisions[p.id])).length;return `<p class="eyebrow">ROUND ${game.round} / SETTLEMENT</p><h1>結果を見て、みんなで進退。</h1><div class="market-facts"><span class="chip ${h.direction==='up'?'positive':'negative'}">${h.direction==='up'?'＋ 上昇':'− 下落'} ${h.bps/100}%</span><span class="chip ${h.gap?'gap-text':''}">${h.gap?'ギャップ相場':'通常相場'}</span><span class="chip">出目 ${h.first}${h.second?' / '+h.second:''}</span></div><p class="muted">全員で「せーの」で続行／資産確定を宣言。<br>宣言した内容を、下のボタンで記録してください。</p><div class="batch-toolbar"><span class="muted" aria-live="polite">記録 ${recorded} / ${active.length}人</span>${action('全員続行で記録','all-continue','secondary')}</div>${resultCards(h,true)}<p class="batch-note">資産確定した人は、以後取引に戻れません。</p><button type="button" class="primary full" data-action="commit-decisions" ${recorded===active.length?'':'disabled'}>全員の進退を確定</button><p class="error" id="form-error" role="alert"></p>`}
function history(){return `<details class="history"><summary>ラウンドの記録（${game.history.length}回）</summary>${game.history.map(h=>`<div class="history-item"><strong>R${h.round} · ${h.direction==='up'?'＋':'−'}${h.bps/100}% · ${h.gap?'ギャップ':'通常'} · 出目 ${h.first}${h.second?` / ${h.second}`:''}</strong>${h.results.map(r=>`<p>${escape(game.players.find(p=>p.id===r.id).name)}：${r.side==='buy'?'買い':'売り'} ${r.leverage}倍 · ${money(r.before)} → ${money(r.after)}</p>`).join('')}</div>`).join('')}</details>`}
function ending(){const ws=winners(game),ranked=[...game.players].sort((a,b)=>BigInt(a.wealth)>BigInt(b.wealth)?-1:BigInt(a.wealth)<BigInt(b.wealth)?1:0);return `<section class="surface end-surface"><p class="eyebrow">FINAL RESULTS / ${game.round} ROUNDS</p>${stageBadge()}${decisionSummary()}<h1>最後に、いくら残せた？</h1><div class="ending"><p>${ws.length>1?'同率勝利':ws.length?'WINNER':'NO WINNER'}</p><h2>${ws.length?ws.map(p=>escape(p.name)).join('・'):'勝者なし'}</h2><p>${ws.length?`最終資産 ${money(ws[0].wealth)}`:'正の資産を残したプレイヤーはいません。'}</p></div><p class="muted">最高到達資産も、最大取引額も、全員の記録に残ります。</p><div class="table-wrap"><table><thead><tr><th>プレイヤー</th><th>初期資産</th><th>最高到達資産</th><th>最大取引額</th><th>最終資産</th></tr></thead><tbody>${ranked.map(p=>`<tr><td><strong>${escape(p.name)}</strong><small>${labels[p.status]}</small></td><td>100.0万円</td><td>${money(p.peak)}</td><td>${money(p.maxPosition)}</td><td class="${BigInt(p.wealth)<0n?'negative':ws.some(w=>w.id===p.id)?'positive':''}"><strong>${money(p.wealth)}</strong></td></tr>`).join('')}</tbody></table></div>${game.history.length?`<section class="last-settlement"><h3>第${game.history.at(-1).round}ラウンドの精算</h3><p class="muted">${game.history.at(-1).direction==='up'?'＋':'−'}${game.history.at(-1).bps/100}% · ${game.history.at(-1).gap?'ギャップ相場':'通常相場'}</p>${resultCards(game.history.at(-1))}</section>`:''}${history()}${action('もう一度遊ぶ','reset','secondary full')}</section>`}
function render(){
 if(!game){root.innerHTML=setup();if(storageError)root.insertAdjacentHTML('afterbegin','<p class="storage-warning">このブラウザでは途中保存が使えません。プレイ中はページを閉じないでください。</p>');return}
 let content='';switch(game.phase){case'order':content=order();break;case'orders-revealed':case'dice':case'shock':case'drawing':content=marketView();break;case'results':content=resultView();break;case'end':root.innerHTML=`<div class="game-layout">${ending()}</div>`;return;default:game=null;update();return}
 const steps={order:'注文の秘密入力','orders-revealed':'注文公開',dice:'値動き',shock:'急変判定',drawing:'相場抽選',results:'精算・進退の一括記録'};
 root.innerHTML=`${storageError?'<p class="storage-warning">途中保存が使えません。プレイ中はページを閉じないでください。</p>':''}<div class="game-layout"><section class="surface"><div class="round-top"><strong>ROUND ${String(game.round).padStart(2,'0')} <span class="muted">/ 12</span></strong><span>${steps[game.phase]}</span></div>${stageBadge()}<div class="round-track" aria-hidden="true">${Array.from({length:12},(_,i)=>`<span class="${i+1<game.round?'done':i+1===game.round?'current':''}"></span>`).join('')}</div>${content}</section>${publicBoard()}</div>`;
}
function setLeverage(value){draftLeverage=value;const valid=Number.isInteger(value)&&value>=1&&value<=100;document.querySelector('#position-value').textContent=valid?money(BigInt(current().wealth)*BigInt(value)):'1〜100の整数を入力';document.querySelector('#order-submit').disabled=!draftSide||!valid;const range=document.querySelector('#leverage-range');if(valid)range.value=String(value)}
function recordDirection(direction){if(game.phase!=='orders-revealed'||game.mode!=='manual')throw Error('相場方向は確定済みです');game.direction=direction;game.phase='dice';update()}
function recordFace(n){if(game.mode!=='manual')throw Error('実物入力モードではありません');if(game.phase==='dice'){game.first=n;game.phase=n===6?'shock':'market-ready'}else if(game.phase==='shock'){game.second=n;game.phase='market-ready'}else throw Error('出目は確定済みです');if(game.phase==='market-ready')resolveRound(game);update()}
async function drawMarket(){const target=game;prepareAutoMarket(target);drawStep=0;update();const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const pause=ms=>new Promise(r=>setTimeout(r,reduced?0:ms));await pause(450);if(game!==target||target.phase!=='drawing')return;drawStep=1;render();if(target.first===6){await pause(550);if(game!==target||target.phase!=='drawing')return;drawStep=2;render()}await pause(400);if(game!==target||target.phase!=='drawing')return;resolveRound(target);update()}

root.addEventListener('input',e=>{const el=e.target;if(el.dataset.name!==undefined)setupNames[Number(el.dataset.name)]=el.value;if(el.id==='leverage')setLeverage(Number(el.value));if(el.id==='leverage-range'){document.querySelector('#leverage').value=el.value;setLeverage(Number(el.value))}});
root.addEventListener('submit',e=>{e.preventDefault();try{if(e.target.id==='setup-form'){game=createGame(setupNames.slice(0,setupCount),setupMode,setupStage);update()}if(e.target.id==='order-form'){submitOrder(game,{side:draftSide,leverage:Number(document.querySelector('#leverage').value)});draftSide=null;draftLeverage=1;update()}}catch(err){document.querySelector('#form-error').textContent=err.message}});
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;try{
 if(b.dataset.count){setupCount=Number(b.dataset.count);render();return}
 if(b.dataset.mode){setupMode=b.dataset.mode;render();return}
 if(b.dataset.stage&&!game){getStage(b.dataset.stage);setupStage=b.dataset.stage;render();return}
 if(b.dataset.side){draftSide=b.dataset.side;render();return}
 if(b.dataset.adjust){const input=document.querySelector('#leverage'),v=Number(input.value);input.value=String(Math.max(1,Math.min(100,(Number.isFinite(v)?Math.round(v):1)+Number(b.dataset.adjust))));setLeverage(Number(input.value));return}
 if(b.dataset.decision&&b.dataset.player!==undefined){const id=Number(b.dataset.player),player=game?.players.find(p=>p.id===id);if(game?.phase!=='results'||player?.status!=='active'||!['continue','fix'].includes(b.dataset.decision))return;game.decisions[id]=b.dataset.decision;update(false);document.querySelector(`[data-player="${id}"][data-decision="${b.dataset.decision}"]`)?.focus({preventScroll:true});return}
 if(b.dataset.direction){recordDirection(b.dataset.direction);return}
 if(b.dataset.face){recordFace(Number(b.dataset.face));return}
 switch(b.dataset.action){
 case'reset':document.querySelector('#reset-dialog').showModal();return;
 case'draw-market':void drawMarket().catch(err=>console.error(err));return;
 case'all-continue':if(game?.phase!=='results')return;game.decisions=Object.fromEntries(activePlayers(game).map(p=>[p.id,'continue']));update(false);document.querySelector('[data-action="all-continue"]')?.focus({preventScroll:true});return;
 case'commit-decisions':commitDecisions(game);draftSide=null;draftLeverage=1;break;
 default:return;
 }update();
 }catch(err){const error=document.querySelector('#form-error');if(error)error.textContent=err.message;else console.error(err)}});
document.querySelector('#rules-open').onclick=showRules;
document.querySelector('#rules-close').onclick=()=>document.querySelector('#rules').close();
document.querySelector('#reset-cancel').onclick=()=>document.querySelector('#reset-dialog').close();
document.querySelector('#reset-confirm').onclick=()=>{document.querySelector('#reset-dialog').close();game=null;draftSide=null;update()};
function clearDrafts(){draftSide=null;draftLeverage=1;if(game?.phase==='order')update(false)}
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearDrafts()});
window.addEventListener('pageshow',e=>{if(e.persisted)clearDrafts()});
function publicState(){if(!game)return {phase:'setup'};return {phase:game.phase,round:game.round,stage:game.stage??'classic',stageName:activeStage().name,players:game.players.map(p=>({...p,wealthDisplay:money(p.wealth)})),pendingOrders:Object.keys(game.orders).length,pendingDecisions:Object.keys(game.decisions).length};}
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}};
 register({name:'read_public_game_state',description:'Read public player balances, statuses and round. Secret choices are never returned.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('No arguments accepted');return publicState()}});
 register({name:'start_fx_survival_game',description:'Start a new 2–6 player game from the setup screen only. Does not enter or submit secret player choices.',inputSchema:{type:'object',properties:{names:{type:'array',minItems:2,maxItems:6,items:{type:'string',minLength:1,maxLength:20}},mode:{type:'string',enum:['auto','manual']},stage:{type:'string',enum:Object.keys(STAGES)}},required:['names'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(game)throw Error('A game is already in progress');if(!input||Object.keys(input).some(k=>!['names','mode','stage'].includes(k))||!Array.isArray(input.names)||input.names.some(n=>typeof n!=='string'||n.length>20)||input.mode&&!['auto','manual'].includes(input.mode))throw Error('Invalid setup');game=createGame(input.names,input.mode||'auto',input.stage??'classic');update();return publicState()}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
save();render();
